import{_ as o}from"./plugin-vue_export-helper-c27b6911.js";import{r as p,o as c,c as d,a,b as s,d as e,e as t}from"./app-09e0be14.js";const l={},i=t(`<h1 id="pv-命令使用教程-版本-1-10-2" tabindex="-1"><a class="header-anchor" href="#pv-命令使用教程-版本-1-10-2" aria-hidden="true">#</a> pv 命令使用教程（版本 1.10.2）</h1><blockquote><p><strong>pv</strong>（Pipe Viewer）是一个基于终端的管道监视器，它通过一条管道传输数据，并显示进度信息：当前传输速率、已用时间、剩余时间、完成百分比和传输总量。它常用于监控大型文件复制、压缩解压、数据库导入、备份恢复等耗时任务的实时进度。</p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p><code>pv</code> 全称 <strong>Pipe Viewer</strong>，是一个小巧而强大的命令行工具。它的核心作用是<strong>夹在管道中间监视数据流量</strong>，让你实时看到数据从一端流向另一端的速度和进度。</p><p>典型应用场景：</p><ul><li>监控 <code>tar</code>、<code>gzip</code>、<code>bzip2</code>、<code>xz</code> 等压缩/解压过程的实时进度；</li><li>监控大文件复制（<code>cp</code>）、<code>dd</code> 镜像写入的进度；</li><li>监控 MySQL/PostgreSQL 数据库导入、逻辑备份的进度；</li><li>监控网络传输、日志流等任何管道数据的流量；</li><li>需要限速（如限制磁盘 IO 或网络带宽）的场景。</li></ul><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装、升级、卸载：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装 pv</span>
brew <span class="token function">install</span> <span class="token function">pv</span>

<span class="token comment"># 升级 pv</span>
brew upgrade <span class="token function">pv</span>

<span class="token comment"># 卸载 pv</span>
brew uninstall <span class="token function">pv</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证安装成功并查看版本：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">pv</span> <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>输出示例：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>pv 1.10.2 - Copyright 2024 Andrew Wood
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,13),r={href:"https://brew.sh",target:"_blank",rel:"noopener noreferrer"},u=a("p",null,[s("在 Linux 发行版上也可通过系统包管理器安装（如 "),a("code",null,"apt install pv"),s(" / "),a("code",null,"yum install pv"),s(" / "),a("code",null,"dnf install pv"),s("）。")],-1),v=t(`<h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>-p</code></td><td>显示进度百分比（默认开启）</td><td><code>pv -p file</code></td></tr><tr><td><code>-t</code></td><td>显示已用时间</td><td><code>pv -t file</code></td></tr><tr><td><code>-r</code></td><td>显示当前传输速率</td><td><code>pv -r file</code></td></tr><tr><td><code>-e</code></td><td>显示已消耗时间</td><td><code>pv -e file</code></td></tr><tr><td><code>-b</code></td><td>显示已传输字节数</td><td><code>pv -b file</code></td></tr><tr><td><code>-a</code></td><td>显示平均传输速率</td><td><code>pv -a file</code></td></tr><tr><td><code>-s SIZE</code></td><td>指定预期总大小（配合百分比使用）</td><td><code>pv -s 1G file</code></td></tr><tr><td><code>-n</code></td><td>以纯数字输出（适合脚本解析）</td><td><code>pv -n file</code></td></tr><tr><td><code>-q</code></td><td>安静模式，仅显示错误信息</td><td><code>pv -q file</code></td></tr><tr><td><code>-L RATE</code></td><td>限制传输速率（如 <code>-L 10m</code> 表示 10MB/s）</td><td><code>pv -L 10m file</code></td></tr><tr><td><code>-c</code></td><td>使用光标定位（配合多行信息刷新）</td><td><code>pv -c file</code></td></tr><tr><td><code>-N NAME</code></td><td>为进度条命名（多管道任务区分）</td><td><code>pv -N &quot;copy&quot; file</code></td></tr><tr><td><code>-w WIDTH</code></td><td>指定终端宽度</td><td><code>pv -w 80 file</code></td></tr><tr><td><code>-f</code></td><td>强制显示（标准输出非终端时也显示）</td><td><code>pv -f file</code></td></tr></tbody></table><p>最常用的组合是把多个参数叠加，例如 <code>pv -ptebar file</code> 会同时显示百分比、时间、字节数、速率、平均速率和进度条。</p><p><strong>其他实用参数补充</strong>：</p><table><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>-B BYTES</code></td><td>设置缓冲区大小（默认 512KiB）</td><td><code>pv -B 4M file</code></td></tr><tr><td><code>-R PID</code></td><td>绑定到指定 PID 的已运行 pv 进程</td><td><code>pv -R 12345</code></td></tr><tr><td><code>-i SECS</code></td><td>设置刷新间隔秒数（配合 <code>-c</code> 使用）</td><td><code>pv -i 2 -c file</code></td></tr><tr><td><code>-E ERRS</code></td><td>允许忽略指定数量的传输错误</td><td><code>pv -E 5 file</code></td></tr><tr><td><code>-y</code></td><td>跳过提示（当输入不是常规文件时）</td><td><code>pv -y file</code></td></tr><tr><td><code>-T</code></td><td>配合 <code>-R</code> 从目标进程读取计时信息</td><td><code>pv -R PID -T</code></td></tr><tr><td><code>-W</code></td><td>等待数据到达后再开始显示</td><td><code>pv -W file</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-监视大文件复制进度" tabindex="-1"><a class="header-anchor" href="#示例-1-监视大文件复制进度" aria-hidden="true">#</a> 示例 1：监视大文件复制进度</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备一个测试文件（生成 200MB 随机数据）</span>
<span class="token function">dd</span> <span class="token assign-left variable">if</span><span class="token operator">=</span>/dev/zero <span class="token assign-left variable">of</span><span class="token operator">=</span>/tmp/bigfile <span class="token assign-left variable">bs</span><span class="token operator">=</span>1M <span class="token assign-left variable">count</span><span class="token operator">=</span><span class="token number">200</span>

<span class="token comment"># 用 pv 监视复制进度</span>
<span class="token function">pv</span> /tmp/bigfile <span class="token operator">&gt;</span> /tmp/bigfile.copy
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行后你会看到类似下面的实时输出：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code> 200MiB 0:00:00 [ 585MiB/s] [============================&gt;] 100%
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="示例-2-监视-tar-打包解压进度" tabindex="-1"><a class="header-anchor" href="#示例-2-监视-tar-打包解压进度" aria-hidden="true">#</a> 示例 2：监视 tar 打包解压进度</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 打包并监视进度（把目录打包成 tar 文件）</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - /path/to/your/folder <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">du</span> <span class="token parameter variable">-sb</span> /path/to/your/folder <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span> <span class="token operator">&gt;</span> backup.tar

<span class="token comment"># 解压并监视进度（先看压缩包大小）</span>
<span class="token function">ls</span> <span class="token parameter variable">-lh</span> backup.tar
<span class="token comment"># 假设压缩包大小为 1.2G，则：</span>
<span class="token function">pv</span> backup.tar <span class="token operator">|</span> <span class="token function">tar</span> <span class="token parameter variable">-xf</span> - <span class="token parameter variable">-C</span> /path/to/extract/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>小技巧</strong>：<code>-s</code> 参数指定总大小，这样 <code>tar</code> 打包时才能正确显示百分比。</p><h3 id="示例-3-限速传输-限制-io-或带宽" tabindex="-1"><a class="header-anchor" href="#示例-3-限速传输-限制-io-或带宽" aria-hidden="true">#</a> 示例 3：限速传输（限制 IO 或带宽）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 限制复制速度为 10MB/s</span>
<span class="token function">pv</span> <span class="token parameter variable">-L</span> 10m /tmp/bigfile <span class="token operator">&gt;</span> /tmp/bigfile.slow

<span class="token comment"># 结合 ssh 限制传输带宽（避免占满带宽）</span>
<span class="token function">pv</span> <span class="token parameter variable">-L</span> 5m /tmp/bigfile <span class="token operator">|</span> <span class="token function">ssh</span> user@host <span class="token string">&quot;cat &gt; /tmp/bigfile.remote&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-数据库导入进度监视" tabindex="-1"><a class="header-anchor" href="#示例-4-数据库导入进度监视" aria-hidden="true">#</a> 示例 4：数据库导入进度监视</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 导入 SQL 到 MySQL 并监视进度（先看文件大小）</span>
<span class="token function">ls</span> <span class="token parameter variable">-lh</span> /tmp/dump.sql
<span class="token comment"># 假设文件为 800M</span>
<span class="token function">pv</span> /tmp/dump.sql <span class="token operator">|</span> mysql <span class="token parameter variable">-u</span> root <span class="token parameter variable">-p</span> your_database

<span class="token comment"># 带总大小信息，显示百分比</span>
<span class="token function">pv</span> <span class="token parameter variable">-s</span> 800M /tmp/dump.sql <span class="token operator">|</span> mysql <span class="token parameter variable">-u</span> root <span class="token parameter variable">-p</span> your_database
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-用-n-输出纯数字方便脚本处理" tabindex="-1"><a class="header-anchor" href="#_1-用-n-输出纯数字方便脚本处理" aria-hidden="true">#</a> 1. 用 <code>-n</code> 输出纯数字方便脚本处理</h3><p><code>-n</code> 模式每次输出一个数字（0-100），配合循环可以做成简易监控脚本：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">pv</span> <span class="token parameter variable">-n</span> /tmp/bigfile <span class="token operator">&gt;</span> /tmp/out <span class="token operator">|</span> <span class="token keyword">while</span> <span class="token builtin class-name">read</span> i<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">echo</span> <span class="token string">&quot;已完成 <span class="token variable">$i</span>%&quot;</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-多管道任务用-n-命名区分" tabindex="-1"><a class="header-anchor" href="#_2-多管道任务用-n-命名区分" aria-hidden="true">#</a> 2. 多管道任务用 <code>-N</code> 命名区分</h3><p>多个管道并行时，用 <code>-N</code> 给每个进度条命名，避免混淆：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">pv</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;file1&quot;</span> /tmp/a <span class="token operator">&gt;</span> /tmp/a.out <span class="token operator">&amp;</span>
<span class="token function">pv</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;file2&quot;</span> /tmp/b <span class="token operator">&gt;</span> /tmp/b.out <span class="token operator">&amp;</span>
<span class="token function">wait</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-用-f-强制显示进度" tabindex="-1"><a class="header-anchor" href="#_3-用-f-强制显示进度" aria-hidden="true">#</a> 3. 用 <code>-f</code> 强制显示进度</h3><p>在非交互式环境（如脚本、CI）中，标准输出不是终端时 <code>pv</code> 默认不显示进度。用 <code>-f</code> 强制显示：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 强制显示进度（适合日志重定向场景）</span>
<span class="token function">pv</span> <span class="token parameter variable">-f</span> /tmp/bigfile <span class="token operator">&gt;</span> /tmp/out <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-与-tar-加密工具组合" tabindex="-1"><a class="header-anchor" href="#_4-与-tar-加密工具组合" aria-hidden="true">#</a> 4. 与 tar + 加密工具组合</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 加密压缩并监视进度</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - /path/to/folder <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">du</span> <span class="token parameter variable">-sb</span> /path/to/folder <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span> <span class="token operator">|</span> <span class="token function">gzip</span> <span class="token parameter variable">-9</span> <span class="token operator">&gt;</span> backup.tar.gz

<span class="token comment"># 配合 openssl 加密</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - /path/to/folder <span class="token operator">|</span> openssl enc -aes-256-cbc <span class="token parameter variable">-salt</span> <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;encrypt&quot;</span> <span class="token operator">&gt;</span> backup.enc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-配置文件与环境变量" tabindex="-1"><a class="header-anchor" href="#_5-配置文件与环境变量" aria-hidden="true">#</a> 5. 配置文件与环境变量</h3><ul><li>pv 没有全局配置文件，所有行为都通过命令行参数控制。</li><li>支持环境变量 <code>PV_DISPLAY</code> 设置默认显示选项，例如 <code>export PV_DISPLAY=&quot;-pteb&quot;</code> 后，所有 pv 调用默认显示百分比、时间、字节数和速率。</li><li>也支持 <code>PV_ESCAPE</code>（设置转义序列）、<code>PV_SLEEP</code>（设置刷新间隔毫秒数）等环境变量。</li></ul><h4 id="常用环境变量一览" tabindex="-1"><a class="header-anchor" href="#常用环境变量一览" aria-hidden="true">#</a> 常用环境变量一览</h4><table><thead><tr><th>环境变量</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>PV_DISPLAY</code></td><td>设置默认显示选项</td><td><code>export PV_DISPLAY=&quot;-ptebar&quot;</code></td></tr><tr><td><code>PV_SLEEP</code></td><td>设置两次刷新之间的毫秒间隔</td><td><code>export PV_SLEEP=1000</code></td></tr><tr><td><code>PV_ESCAPE</code></td><td>设置用于状态行更新的转义序列</td><td><code>export PV_ESCAPE=&quot;\\033[K&quot;</code></td></tr><tr><td><code>PV_REMOTE</code></td><td>远程输出模式（配合 <code>-f</code>）</td><td><code>export PV_REMOTE=1</code></td></tr><tr><td><code>PV_WATCH</code></td><td>从标准输入读取并在屏幕上监视数据</td><td><code>export PV_WATCH=1</code></td></tr><tr><td><code>PV_RSIZE</code></td><td>设置接收缓冲区大小</td><td><code>export PV_RSIZE=1048576</code></td></tr><tr><td><code>PV_WSIZE</code></td><td>设置发送缓冲区大小</td><td><code>export PV_WSIZE=1048576</code></td></tr></tbody></table><p>把这些环境变量写入 <code>~/.bashrc</code>、<code>~/.zshrc</code> 或 <code>~/.profile</code> 即可实现持久化个性化配置。例如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># ~/.zshrc</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">PV_DISPLAY</span><span class="token operator">=</span><span class="token string">&quot;-ptebar&quot;</span>        <span class="token comment"># 默认显示所有主要信息</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">PV_SLEEP</span><span class="token operator">=</span><span class="token number">500</span>               <span class="token comment"># 每 500ms 刷新一次</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="缓冲大小与性能调优" tabindex="-1"><a class="header-anchor" href="#缓冲大小与性能调优" aria-hidden="true">#</a> 缓冲大小与性能调优</h4><ul><li>默认缓冲区大小为 512 KiB，对大多数场景足够。</li><li>在高吞吐管道（如 NVMe、内存盘）上，适当调大缓冲区可减少系统调用开销：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">pv</span> <span class="token parameter variable">-B</span> 8M /dev/nvme0n1 <span class="token operator">&gt;</span> disk.img   <span class="token comment"># 用 8MiB 缓冲区</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>批量使用 pv 时，建议在 shell 配置里设置 <code>PV_SLEEP</code> 为 100~500ms，既能看到流畅进度，又不浪费 CPU。</li></ul><h4 id="组合显示选项的建议" tabindex="-1"><a class="header-anchor" href="#组合显示选项的建议" aria-hidden="true">#</a> 组合显示选项的建议</h4><ul><li>日常交互用 <code>pv -ptebar file</code>：百分比、时间、字节、速率、平均速率、进度条一应俱全。</li><li>网络传输用 <code>pv -rab file</code>：速率与平均值对带宽判断最直观。</li><li>脚本内用 <code>pv -n file</code> 或 <code>pv -q file</code>：避免污染输出。</li></ul><h3 id="_6-多流进度显示-c-光标控制-i-刷新间隔" tabindex="-1"><a class="header-anchor" href="#_6-多流进度显示-c-光标控制-i-刷新间隔" aria-hidden="true">#</a> 6. 多流进度显示（<code>-c</code> 光标控制 + <code>-i</code> 刷新间隔）</h3><p><code>pv</code> 支持在多个管道同时运行时，在同一个终端区域刷新各自的进度条：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 同时监控两个文件的复制进度</span>
<span class="token function">pv</span> <span class="token parameter variable">-c</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;a&quot;</span> /tmp/a <span class="token operator">&gt;</span> /tmp/a.out <span class="token operator">&amp;</span>
<span class="token function">pv</span> <span class="token parameter variable">-c</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;b&quot;</span> /tmp/b <span class="token operator">&gt;</span> /tmp/b.out <span class="token operator">&amp;</span>
<span class="token function">wait</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>-i</code> 指定刷新间隔，减少频繁重绘：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">pv</span> <span class="token parameter variable">-c</span> <span class="token parameter variable">-i</span> <span class="token number">1</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;copy&quot;</span> /tmp/big <span class="token operator">&gt;</span> /tmp/out
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><blockquote><p>注意：<code>-c</code> 依赖光标定位，必须输出到终端（或配合 <code>-f</code> 在合适环境使用），否则进度条会错乱。</p></blockquote><h3 id="_7-精确计算目录大小的可移植写法" tabindex="-1"><a class="header-anchor" href="#_7-精确计算目录大小的可移植写法" aria-hidden="true">#</a> 7. 精确计算目录大小的可移植写法</h3><p><code>du -sb</code> 在部分系统（如 macOS 的 BSD <code>du</code>）上没有 <code>-b</code> 参数。跨平台可用 <code>stat</code> 或 <code>find</code> 替代：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># Linux（GNU stat）</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - folder <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">stat</span> -c%s folder<span class="token variable">)</span></span> <span class="token operator">&gt;</span> folder.tar

<span class="token comment"># macOS（BSD stat）</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - folder <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">stat</span> -f%z folder<span class="token variable">)</span></span> <span class="token operator">&gt;</span> folder.tar
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-没有显示百分比-进度不动" tabindex="-1"><a class="header-anchor" href="#_1-没有显示百分比-进度不动" aria-hidden="true">#</a> 1. 没有显示百分比 / 进度不动</h3><ul><li><strong>原因</strong>：<code>pv</code> 不知道数据总量时无法计算百分比。</li><li><strong>解决</strong>：用 <code>-s</code> 指定总大小，例如 <code>pv -s 500M file</code>。</li></ul><h3 id="_2-输出乱码或重叠" tabindex="-1"><a class="header-anchor" href="#_2-输出乱码或重叠" aria-hidden="true">#</a> 2. 输出乱码或重叠</h3><ul><li><strong>原因</strong>：多行刷新在非终端环境下出错。</li><li><strong>解决</strong>：脚本中使用 <code>-n</code>（纯数字）或 <code>-q</code>（安静），交互终端下可加 <code>-c</code> 启用光标控制。</li></ul><h3 id="_3-s-与-du-的大小不一致导致百分比不准" tabindex="-1"><a class="header-anchor" href="#_3-s-与-du-的大小不一致导致百分比不准" aria-hidden="true">#</a> 3. <code>-s</code> 与 <code>du</code> 的大小不一致导致百分比不准</h3><ul><li><strong>原因</strong>：<code>du -sb</code> 统计的是实际磁盘占用，与文件逻辑大小可能略有差异（如稀疏文件）。</li><li><strong>解决</strong>：用 <code>stat -c%s file</code> 获取文件逻辑大小：<code>pv -s $(stat -c%s file) file</code>。</li></ul><h3 id="_4-性能与-io-开销" tabindex="-1"><a class="header-anchor" href="#_4-性能与-io-开销" aria-hidden="true">#</a> 4. 性能与 IO 开销</h3><ul><li><code>pv</code> 本身开销极低，但在高速管道（如 NVMe 磁盘）上，默认的刷新频率可能略影响吞吐。</li><li>通过环境变量 <code>PV_SLEEP</code> 调大刷新间隔可降低开销：<code>export PV_SLEEP=1000</code>（毫秒）。</li><li>对极致吞吐的场景，可同时调大缓冲区：<code>pv -B 4M -i 2 -f file</code>。</li></ul><h3 id="_5-限速时注意单位" tabindex="-1"><a class="header-anchor" href="#_5-限速时注意单位" aria-hidden="true">#</a> 5. 限速时注意单位</h3><ul><li><code>-L</code> 的单位是字节/秒，支持 <code>k</code>、<code>m</code>、<code>g</code> 后缀（如 <code>-L 10m</code> 表示 10 MB/s，即每秒 10 兆字节），不要与比特混淆（网络带宽常用 <code>Mb/s</code>）。</li><li>当 <code>-L</code> 限制速率低于数据读取能力时，<code>pv</code> 会主动节流，可能让进度条看起来&quot;卡住&quot;，这是正常现象。</li></ul><h3 id="_6-管道退出码" tabindex="-1"><a class="header-anchor" href="#_6-管道退出码" aria-hidden="true">#</a> 6. 管道退出码</h3><ul><li>当上游命令失败时，<code>pv</code> 仍可能成功退出，导致下游继续执行。若需严格判断，可用 <code>set -o pipefail</code>（bash）让管道返回第一个失败命令的退出码。</li></ul><h3 id="_7-文件大小未知且非流式输入" tabindex="-1"><a class="header-anchor" href="#_7-文件大小未知且非流式输入" aria-hidden="true">#</a> 7. 文件大小未知且非流式输入</h3><ul><li><strong>现象</strong>：直接把 <code>pv</code> 接在某个命令后（如 <code>some_cmd | pv &gt; out</code>），只见速率、不见百分比。</li><li><strong>原因</strong>：<code>pv</code> 无法预知总量。</li><li><strong>解决</strong>：若上游能估算总量，手动 <code>-s</code>；否则接受无百分比状态，用 <code>-pt</code> 显示时间与速率即可。</li></ul><h3 id="_8-多流进度条串行-重叠" tabindex="-1"><a class="header-anchor" href="#_8-多流进度条串行-重叠" aria-hidden="true">#</a> 8. 多流进度条串行/重叠</h3><ul><li><strong>现象</strong>：多个 <code>pv</code> 后台并行，进度条互相覆盖、混在一起。</li><li><strong>原因</strong>：每个 <code>pv</code> 独立刷新同一行。</li><li><strong>解决</strong>：全部加 <code>-c</code> 并放在同一终端，或用 <code>-N</code> 命名区分；脚本中建议改用 <code>-n</code> 各自输出。</li></ul><h3 id="_9-l-限速与稀疏文件-空洞" tabindex="-1"><a class="header-anchor" href="#_9-l-限速与稀疏文件-空洞" aria-hidden="true">#</a> 9. <code>-L</code> 限速与稀疏文件/空洞</h3><ul><li><strong>现象</strong>：对包含大量空洞的文件限速复制，速度显示异常。</li><li><strong>原因</strong>：<code>pv</code> 仍会逐字节读取空洞，拖慢整体速度。</li><li><strong>解决</strong>：如需跳过空洞，先用 <code>cp --sparse=always</code>（GNU cp）或 <code>rsync -S</code> 处理，再交给 <code>pv</code> 监视。</li></ul><h3 id="_10-常见报错及应对" tabindex="-1"><a class="header-anchor" href="#_10-常见报错及应对" aria-hidden="true">#</a> 10. 常见报错及应对</h3><ul><li><code>pv: No such file or directory</code>：文件路径错误，检查拼写。</li><li><code>pv: Permission denied</code>：无读取权限，加 <code>sudo</code> 或用对应用户运行。</li><li><code>pv: Interrupted</code>：收到中断信号（如 Ctrl+C），管道任务随之终止，属于正常行为。</li><li><code>pv: /dev/stdin: ...</code>：输入无法读取，确认使用 <code>&lt;</code> 重定向或命名管道方式。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-与-dd-配合做磁盘-分区镜像并限速" tabindex="-1"><a class="header-anchor" href="#_1-与-dd-配合做磁盘-分区镜像并限速" aria-hidden="true">#</a> 1. 与 <code>dd</code> 配合做磁盘/分区镜像并限速</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 备份整块磁盘到镜像文件，限速避免影响线上服务</span>
<span class="token function">sudo</span> <span class="token function">dd</span> <span class="token assign-left variable">if</span><span class="token operator">=</span>/dev/sda <span class="token assign-left variable">bs</span><span class="token operator">=</span>4M <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">sudo</span> blockdev <span class="token parameter variable">--getsize64</span> /dev/sda<span class="token variable">)</span></span> <span class="token operator">|</span> <span class="token function">dd</span> <span class="token assign-left variable">of</span><span class="token operator">=</span>/backup/sda.img <span class="token assign-left variable">bs</span><span class="token operator">=</span>4M

<span class="token comment"># 恢复镜像并监视进度</span>
<span class="token function">pv</span> /backup/sda.img <span class="token operator">|</span> <span class="token function">sudo</span> <span class="token function">dd</span> <span class="token assign-left variable">of</span><span class="token operator">=</span>/dev/sda <span class="token assign-left variable">bs</span><span class="token operator">=</span>4M
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-与-tar-配合做远程备份-网络流式" tabindex="-1"><a class="header-anchor" href="#_2-与-tar-配合做远程备份-网络流式" aria-hidden="true">#</a> 2. 与 <code>tar</code> 配合做远程备份（网络流式）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 本地打包 + 远程解包，全程显示进度</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - /data <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">du</span> <span class="token parameter variable">-sb</span> /data <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span> <span class="token operator">|</span> <span class="token function">ssh</span> user@host <span class="token string">&quot;tar -xf - -C /backup&quot;</span>

<span class="token comment"># 限制网络带宽为 2MB/s</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - /data <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-L</span> 2m <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">du</span> <span class="token parameter variable">-sb</span> /data <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span> <span class="token operator">|</span> <span class="token function">ssh</span> user@host <span class="token string">&quot;cat &gt; /backup/data.tar&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-配合-gzip-xz-压缩解压" tabindex="-1"><a class="header-anchor" href="#_3-配合-gzip-xz-压缩解压" aria-hidden="true">#</a> 3. 配合 <code>gzip</code>/<code>xz</code> 压缩解压</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 压缩并显示进度（用实际大小做 -s 基数，注意是压缩前大小）</span>
<span class="token function">tar</span> <span class="token parameter variable">-cf</span> - /data <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-s</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">du</span> <span class="token parameter variable">-sb</span> /data <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span> <span class="token operator">|</span> <span class="token function">gzip</span> <span class="token parameter variable">-9</span> <span class="token operator">&gt;</span> data.tar.gz

<span class="token comment"># 解压压缩包并显示进度</span>
<span class="token function">pv</span> data.tar.gz <span class="token operator">|</span> <span class="token function">gzip</span> <span class="token parameter variable">-dc</span> <span class="token operator">|</span> <span class="token function">tar</span> <span class="token parameter variable">-xf</span> - <span class="token parameter variable">-C</span> /restore
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-网络下载限速-配合-curl" tabindex="-1"><a class="header-anchor" href="#_4-网络下载限速-配合-curl" aria-hidden="true">#</a> 4. 网络下载限速（配合 <code>curl</code>）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 curl 下载并通过 pv 限速（限制为 5MB/s）</span>
<span class="token function">curl</span> <span class="token parameter variable">-sL</span> https://example.com/big.iso <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-L</span> 5m <span class="token operator">&gt;</span> /tmp/big.iso

<span class="token comment"># 结合 wget，利用 pv 显示进度</span>
<span class="token function">wget</span> -qO- https://example.com/big.iso <span class="token operator">|</span> <span class="token function">pv</span> <span class="token parameter variable">-b</span> <span class="token operator">&gt;</span> /tmp/big.iso
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-写入共享工作区的脚本化监控" tabindex="-1"><a class="header-anchor" href="#_5-写入共享工作区的脚本化监控" aria-hidden="true">#</a> 5. 写入共享工作区的脚本化监控</h3><p>把 pv 的纯数字输出写到文件，供其它脚本轮询，实现&quot;脱离终端&quot;的进度：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token comment"># monitor.sh —— 把进度写入 progress.log，供其他程序读取</span>
<span class="token function">pv</span> <span class="token parameter variable">-n</span> <span class="token parameter variable">-f</span> /tmp/bigfile <span class="token operator">&gt;</span> /tmp/bigfile.copy <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/tmp/progress.log <span class="token operator">&amp;</span>
<span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$!</span>
<span class="token comment"># 模拟下游读取</span>
<span class="token keyword">while</span> <span class="token function">kill</span> <span class="token parameter variable">-0</span> <span class="token variable">$PID</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">printf</span> <span class="token string">&#39;进度: %s%%\\n&#39;</span> <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">tail</span> <span class="token parameter variable">-1</span> /tmp/progress.log<span class="token variable">)</span></span>&quot;</span>
  <span class="token function">sleep</span> <span class="token number">1</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-makefile-自动化集成" tabindex="-1"><a class="header-anchor" href="#_6-makefile-自动化集成" aria-hidden="true">#</a> 6. Makefile 自动化集成</h3><p>在 Makefile 中用 <code>pv</code> 包装耗时的构建/复制步骤，输出进度：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code>BACKUP_DIR  <span class="token operator">:=</span> ./backup
DATA_DIR    <span class="token operator">:=</span> ./data
SIZE_CMD    <span class="token operator">:=</span> du -sb <span class="token variable">$</span><span class="token punctuation">(</span>DATA_DIR<span class="token punctuation">)</span> <span class="token operator">|</span> awk <span class="token string">&#39;{print $$1}&#39;</span>

<span class="token target symbol">backup</span><span class="token punctuation">:</span>
	tar -cf - <span class="token variable">$</span><span class="token punctuation">(</span>DATA_DIR<span class="token punctuation">)</span> <span class="token operator">|</span> pv -s <span class="token variable">$$</span><span class="token punctuation">(</span><span class="token variable">$</span><span class="token punctuation">(</span>SIZE_CMD<span class="token punctuation">)</span><span class="token punctuation">)</span> &gt; <span class="token variable">$</span><span class="token punctuation">(</span>BACKUP_DIR<span class="token punctuation">)</span>/data.tar
	<span class="token operator">@</span>echo <span class="token string">&quot;备份完成: $(BACKUP_DIR)/data.tar&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：Makefile 中 shell 变量需转义为 <code>$$</code>，否则 Make 会提前展开。</p></blockquote><h3 id="_7-ci-集成-github-actions-gitlab-ci" tabindex="-1"><a class="header-anchor" href="#_7-ci-集成-github-actions-gitlab-ci" aria-hidden="true">#</a> 7. CI 集成（GitHub Actions / GitLab CI）</h3><p>在 CI 中 pv 默认不输出（非终端），需要 <code>-f</code> 强制显示，或改用 <code>-n</code> 便于日志分析：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/backup.yml</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">backup</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> sudo apt<span class="token punctuation">-</span>get install <span class="token punctuation">-</span>y pv
      <span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          tar -cf - ./data | pv -f -s $(du -sb ./data | awk &#39;{print $1}&#39;) | gzip -9 &gt; data.tar.gz</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/upload<span class="token punctuation">-</span>artifact@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">name</span><span class="token punctuation">:</span> backup
          <span class="token key atrule">path</span><span class="token punctuation">:</span> data.tar.gz
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>在 CI 中建议输出到日志时关闭进度条重绘，仅保留总字节和速率：<code>pv -f -b -a ...</code>。</p></blockquote><h3 id="_8-批量处理多个文件-循环-并行" tabindex="-1"><a class="header-anchor" href="#_8-批量处理多个文件-循环-并行" aria-hidden="true">#</a> 8. 批量处理多个文件（循环 + 并行）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 串行：逐个文件限速复制</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">f</span> <span class="token keyword">in</span> /tmp/data/*.dat<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token function">pv</span> <span class="token parameter variable">-L</span> 10m <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$f</span>.copy&quot;</span>
<span class="token keyword">done</span>

<span class="token comment"># 并行：多个文件同时限速复制（配合 -N 区分）</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">f</span> <span class="token keyword">in</span> /tmp/data/*.dat<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token function">pv</span> <span class="token parameter variable">-c</span> <span class="token parameter variable">-N</span> <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">basename</span> $f<span class="token variable">)</span></span>&quot;</span> <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token operator">&gt;</span> <span class="token string">&quot;<span class="token variable">$f</span>.copy&quot;</span> <span class="token operator">&amp;</span>
<span class="token keyword">done</span>
<span class="token function">wait</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-生产级实践要点" tabindex="-1"><a class="header-anchor" href="#_9-生产级实践要点" aria-hidden="true">#</a> 9. 生产级实践要点</h3><ul><li><strong>限速</strong>：任何可能影响生产服务的复制/传输都加上 <code>-L</code> 限速，避免占满磁盘 IO 或带宽。</li><li><strong>缓冲</strong>：大文件备份用 <code>-B 4M</code>~<code>-B 8M</code> 提升吞吐。</li><li><strong>退出码</strong>：在脚本顶部加 <code>set -o pipefail</code>，确保管道任一段失败都返回非零退出码，CI 才能正确判失败。</li><li><strong>日志友好</strong>：脚本/CI 中统一用 <code>-n</code>（纯数字）或 <code>-b</code>（仅字节），便于机器解析。</li><li><strong>权限</strong>：涉及系统设备（如 <code>/dev/sda</code>）务必用 <code>sudo</code>，并在 <code>dd</code> 时核对目标设备，避免误覆盖。</li></ul><h2 id="参考链接" tabindex="-1"><a class="header-anchor" href="#参考链接" aria-hidden="true">#</a> 参考链接</h2>`,96),b={href:"https://www.ivarch.com/programs/pv.shtml",target:"_blank",rel:"noopener noreferrer"},k={href:"https://formulae.brew.sh/formula/pv",target:"_blank",rel:"noopener noreferrer"};function m(h,g){const n=p("ExternalLinkIcon");return c(),d("div",null,[i,a("blockquote",null,[a("p",null,[s("提示：如果你的 Homebrew 尚未安装，请先参考 "),a("a",r,[s("brew.sh"),e(n)]),s(" 安装 Homebrew。")]),u]),v,a("ul",null,[a("li",null,[a("a",b,[s("pv 官方文档（man page）"),e(n)])]),a("li",null,[a("a",k,[s("Homebrew pv 页面"),e(n)])])])])}const x=o(l,[["render",m],["__file","pv.html.vue"]]);export{x as default};
